import { describe, it, expect } from 'vitest';
import {
  ID_LENGTH,
  ID_PATTERN,
  assertValidId,
  generateId,
  isValidId,
  timestampFromId,
  toCanonicalId,
} from '../../src/utils/id.js';

/**
 * Canonical id rules.
 *
 * These are the contract every provider shares: 24 lowercase hex characters,
 * generated by the application (never by the database), with an ObjectId-compatible
 * layout so `ORDER BY id` and `ORDER BY _id` agree.
 */
describe('utils/id', () => {
  describe('isValidId — accepts only canonical 24-hex ids', () => {
    it('accepts lowercase and uppercase 24-hex strings', () => {
      expect(isValidId('65a000000000000000000001')).toBe(true);
      expect(isValidId('65A000000000000000000001')).toBe(true);
      expect(isValidId(generateId())).toBe(true);
    });

    it.each([
      ['too short', '65a0'],
      ['23 characters', '65a00000000000000000000'],
      ['25 characters', '65a0000000000000000000001'],
      ['12-character ObjectId shorthand', 'aaaaaaaaaaaa'],
      ['non-hex characters', 'zzzzzzzzzzzzzzzzzzzzzzzz'],
      ['hex with a hyphen', '65a0000-0000000000000000'],
      ['leading/trailing whitespace', ' 65a000000000000000000001 '],
      ['empty string', ''],
      ['a uuid', '123e4567-e89b-12d3-a456-426614174000'],
    ])('rejects %s', (_label, value) => {
      expect(isValidId(value)).toBe(false);
    });

    it.each([
      ['number', 12_345],
      ['null', null],
      ['undefined', undefined],
      ['object', {}],
      ['array', ['65a000000000000000000001']],
      ['boolean', true],
      ['buffer', Buffer.alloc(12)],
    ])('rejects a non-string value (%s)', (_label, value) => {
      expect(isValidId(value)).toBe(false);
    });
  });

  it('exposes the pattern and length used by route validation', () => {
    expect(ID_PATTERN.test('65a000000000000000000001')).toBe(true);
    expect(ID_LENGTH).toBe(24);
    expect(ID_PATTERN.source).toBe('^[0-9a-fA-F]{24}$');
  });

  describe('generateId', () => {
    it('always produces 24 lowercase hex characters', () => {
      for (let i = 0; i < 500; i += 1) {
        const id = generateId();
        expect(id).toMatch(ID_PATTERN);
        expect(id).toBe(id.toLowerCase());
        expect(id).toHaveLength(24);
      }
    });

    it('never repeats', () => {
      const ids = new Set(Array.from({ length: 5000 }, () => generateId()));
      expect(ids.size).toBe(5000);
    });

    it('keeps the ObjectId layout: timestamp prefix + 5 random bytes + 3 counter bytes', () => {
      const now = new Date('2026-01-01T00:00:00.000Z');
      const id = generateId(now);
      expect(id.slice(0, 8)).toBe((now.getTime() / 1000).toString(16).padStart(8, '0'));
      expect(timestampFromId(id).getTime()).toBe(now.getTime());
    });

    it('is strictly increasing within a second (counter), so `id DESC` is creation order', () => {
      const now = new Date('2026-01-01T00:00:00.000Z');
      const ids = Array.from({ length: 100 }, () => generateId(now));
      const sorted = [...ids].sort();
      expect(sorted).toEqual(ids);
    });

    it('advances the prefix when the clock advances', () => {
      const earlier = generateId(new Date('2026-01-01T00:00:00.000Z'));
      const later = generateId(new Date('2026-01-01T00:00:01.000Z'));
      expect(later > earlier).toBe(true);
    });
  });

  describe('assertValidId / toCanonicalId', () => {
    it('returns the lowercased id', () => {
      expect(assertValidId('65A000000000000000000001')).toBe('65a000000000000000000001');
    });

    it('throws a TypeError for a malformed id', () => {
      expect(() => assertValidId('nope')).toThrow(TypeError);
      expect(() => assertValidId(42)).toThrow(TypeError);
    });

    it('normalises driver-style values through toString()', () => {
      expect(toCanonicalId({ toString: () => '65A000000000000000000001' })).toBe(
        '65a000000000000000000001',
      );
      expect(toCanonicalId('65a000000000000000000001')).toBe('65a000000000000000000001');
    });

    it('rejects a driver-style value that is not canonical', () => {
      expect(() => toCanonicalId({ toString: () => 'aaaaaaaaaaaa' })).toThrow(TypeError);
    });
  });

  it('timestampFromId rejects malformed ids', () => {
    expect(() => timestampFromId('short')).toThrow(TypeError);
  });
});
